local a = game.ReplicatedStorage.Shared.Assets local s = a.Source s = s:gsub("%-%- WORLD ART START.-%-%- WORLD ART END\n", "") local block = "-- WORLD ART START\nAssets.Floors = Assets.Floors or {}\nAssets.Floors.Sky = \"rbxassetid://118334347239534\"\nAssets.Floors.Candy = \"rbxassetid://104839541243931\"\nAssets.Floors.Space = \"rbxassetid://128786772816458\"\nAssets.Floors.Lair = \"rbxassetid://86492301122667\"\nAssets.Portals = Assets.Portals or {}\nAssets.Portals.Sky = \"rbxassetid://133903079187908\"\nAssets.Portals.Candy = \"rbxassetid://122790115664473\"\nAssets.Portals.Space = \"rbxassetid://123080754434628\"\nAssets.Portals.Lair = \"rbxassetid://140172290427373\"\n-- WORLD ART END\n" local n s, n = s:gsub("\nreturn Assets", function() return "\n" .. block .. "return Assets" end, 1) if n == 1 then a.Source = s print("Floors + portals saved! Press Play.") else warn("Could not find Assets - tell Claude") end
